<?php use App\Support\App;$u=App::requireAuth();$q=App::db()->prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY id DESC LIMIT 200');$q->execute([$u['id']]);$rows=$q->fetchAll();$title='Transactions';require __DIR__.'/../layouts/head.php';require __DIR__.'/../components/app_start.php';?><div class="flex justify-between items-end"><div><h1 class="page-title">Transactions</h1><p class="page-sub">Ledger seluruh perubahan saldo akun.</p></div><div class="text-right"><span class="text-xs text-zinc-500">BALANCE</span><div class="font-bold">Rp<?=number_format($u['balance'],0,',','.')?></div></div></div><div class="saas-card mt-6 overflow-auto"><table class="w-full text-sm min-w-[650px]"><thead><tr><th>Type</th><th>Reference</th><th>Amount</th><th>Before</th><th>After</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t" style="border-color:var(--line)"><td><span class="badge"><?=htmlspecialchars($r['type'])?></span></td><td><?=htmlspecialchars($r['reference']??'-')?></td><td class="font-semibold"><?=($r['amount']>=0?'+':'')?>Rp<?=number_format($r['amount'],0,',','.')?></td><td>Rp<?=number_format($r['balance_before'],0,',','.')?></td><td>Rp<?=number_format($r['balance_after'],0,',','.')?></td><td class="text-zinc-500"><?=htmlspecialchars($r['created_at'])?></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="p-10 text-center text-zinc-500">Belum ada transaksi.</div><?php endif?></div><?php require __DIR__.'/../components/app_end.php';require __DIR__.'/../layouts/foot.php';?>